import {VISUAL_VIEWS} from './visual-router.js';

export function renderVisualDock({esc,icon}){
  return `<div class="visual-dock"><div class="visual-dock-heading"><span>METTRE EN SCÈNE</span><button data-action="visual-desk">Régie visuelle ${icon('arrowUp')}</button></div><div class="visual-dock-choices">${VISUAL_VIEWS.map(v=>`<button data-action="visual-present" data-visual-id="${v.id}" title="${esc(v.description)} — écran ${v.screen}"><span class="visual-dock-glyph">${icon(v.icon)}</span><strong>${v.short}</strong><small>${v.screen}</small></button>`).join('')}</div></div>`;
}
export function renderVisualDesk({project,provider,receipt='',esc,icon}){
  return `<section class="visual-desk" data-visual-desk data-project="${esc(project.id)}"><div class="visual-desk-intro"><span class="tag tag-red">JARVIS / RÉGIE VISUELLE</span><h3>LA BONNE VUE.<br><em>AU BON MOMENT.</em></h3><p>Une demande, une scène, un retour de l’écran.</p></div><div class="visual-stage-map" aria-label="Rôle des trois moniteurs"><div><b>01</b><span>ATELIER</span><small>Parc & production</small></div><div class="central"><img src="./assets/logo.webp" alt=""><b>02</b><span>JARVIS</span><small>Votre intention</small></div><div><b>03</b><span>CRÉATION</span><small>Œuvres & modèles</small></div></div><form id="visual-command-form"><label for="visual-command-input">QUEL VISUEL VOUS AIDERAIT ?</label><div class="visual-command-field"><input id="visual-command-input" name="command" maxlength="250" placeholder="Montre le volume de la pièce…" autocomplete="off" required><button type="submit" aria-label="Choisir et afficher la vue">${icon('arrow')}</button></div><fieldset class="visual-provider-picker"><legend class="sr-only">Moteur de choix des vues</legend><label><input type="radio" name="provider" value="local" checked><span>Raccourcis locaux</span></label><label><input type="radio" name="provider" value="typesafe" ${provider.configured?'':'disabled'}><span>Avec Jev</span></label><button type="button" data-action="visual-provider-refresh" aria-label="Vérifier la disponibilité de Jev">${icon('rotate')}</button></fieldset><p class="visual-provider-state" data-visual-provider-state>${provider.connected?'Jev a répondu sur ce poste.':provider.configured?'Jev configuré · premier appel à tester.':'Jev à raccorder · les raccourcis locaux sont disponibles.'}</p></form><div class="visual-decision-status" role="status" data-visual-status>${esc(receipt||'Sélectionnez directement une scène ou décrivez-la.')}</div><div class="visual-scene-grid">${VISUAL_VIEWS.map(v=>`<button class="visual-scene-card" data-action="visual-present" data-visual-id="${v.id}" ${v.id==='model'&&!project.pieces.length?'disabled':''}><img src="./assets/${v.image}" alt="" loading="lazy"><div class="visual-scene-shade"></div><span class="visual-scene-number">${v.screen} / ${v.target==='atelier'?'GAUCHE':'DROITE'}</span><span class="visual-scene-icon">${icon(v.icon)}</span><div><strong>${esc(v.label)}</strong><small>${esc(v.description)}</small></div><span class="visual-scene-arrow">${icon('arrowUp')}</span></button>`).join('')}</div><div class="visual-desk-foot"><button class="button" data-action="signature">${icon('spark')} Signature BOJ.ART</button><button class="button" data-action="screens">${icon('screens')} Installer les écrans</button></div><details class="visual-connection-details"><summary>Comment raccorder Jev ?</summary><p>La passerelle prévue sur la tour garde la clé TypeSafe côté serveur. Le choix de vue est envoyé au service Jev quand vous sélectionnez « Avec Jev ». Le modèle, le mouvement et le rendu restent dans le dashboard.</p><p>Le service Jev hébergé et la reconnaissance vocale locale sont deux raccordements distincts. Une clé configurée ne prouve pas qu’un appel a réussi.</p><a href="https://docs.typesafe.ai/introduction/quickstart" target="_blank" rel="noopener">Documentation officielle ${icon('arrowUp')}</a></details></section>`;
}
